using Garage.BUS;using Garage.DAL;using Garage.DTO;namespace Garage.GUI;public class MainForm:Form{readonly GarageService s=new();readonly DataGridView cars=G(),parts=G(),customers=G(),repairs=G();static DataGridView G()=>new(){Dock=DockStyle.Fill,ReadOnly=true,AllowUserToAddRows=false,AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.Fill,SelectionMode=DataGridViewSelectionMode.FullRowSelect};public MainForm(){Text="HỆ THỐNG QUẢN LÝ GARAGE VÀ BẢO DƯỠNG Ô TÔ - BÀI 6.4";Width=1200;Height=750;var t=new TabControl{Dock=DockStyle.Fill};Controls.Add(t);t.TabPages.Add(Page("Tra cứu xe",cars,Bar(B("Tìm xe",()=>cars.DataSource=s.SearchCars(Prompt("Biển số hoặc tên chủ xe:"))),B("Tải lại",()=>cars.DataSource=s.SearchCars("")),B("Tiếp nhận xe mới",AddCar))));t.TabPages.Add(Page("Khách hàng",customers,Bar(B("Tải lại",()=>customers.DataSource=s.Customers()))));t.TabPages.Add(Page("Phụ tùng",parts,Bar(B("Thêm phụ tùng",AddPart),B("Tải lại",()=>parts.DataSource=s.Parts()))));t.TabPages.Add(Page("Phiếu sửa chữa",repairs,Bar(B("Lập phiếu sửa chữa",CreateRepair),B("Thanh toán phiếu đang chọn",Pay),B("Tải lại",()=>repairs.DataSource=s.Repairs()))));Shown+=(_,_)=>Safe(()=>{using var c=Db.Open();RefreshAll();});}void RefreshAll(){cars.DataSource=s.SearchCars("");parts.DataSource=s.Parts();customers.DataSource=s.Customers();repairs.DataSource=s.Repairs();}TabPage Page(string n,DataGridView g,Control b){var p=new TabPage(n);p.Controls.Add(g);p.Controls.Add(b);return p;}Control Bar(params Control[] c){var p=new FlowLayoutPanel{Dock=DockStyle.Top,Height=48};p.Controls.AddRange(c);return p;}Button B(string n,Action a){var b=new Button{Text=n,AutoSize=true,Height=32};b.Click+=(_,_)=>Safe(a);return b;}void AddCar(){string n=Prompt("Tên chủ xe:"),phone=Prompt("Điện thoại:"),address=Prompt("Địa chỉ:"),plate=Prompt("Biển số:"),model=Prompt("Hiệu xe:");if(n==""||plate=="")return;int.TryParse(Prompt("Năm sản xuất:",DateTime.Now.Year.ToString()),out int year);s.AddCustomerCar(n,phone,address,plate,model,year);RefreshAll();}void AddPart(){string n=Prompt("Tên phụ tùng:");if(n=="")return;decimal price=decimal.Parse(Prompt("Đơn giá:","100000"));int stock=int.Parse(Prompt("Số lượng tồn:","10"));s.AddPart(n,price,stock);parts.DataSource=s.Parts();}void CreateRepair(){string plate=Prompt("Biển số xe:"),note=Prompt("Nội dung sửa chữa:");if(plate=="")return;int id=int.Parse(Prompt("Mã phụ tùng:","1"));int qty=int.Parse(Prompt("Số lượng:","1"));decimal labor=decimal.Parse(Prompt("Tiền công:","0"));s.CreateRepair(plate,note,new(){new RepairItem{MaPhuTung=id,SoLuong=qty,TienCong=labor}});RefreshAll();MessageBox.Show("Đã lập phiếu, trừ kho trong một transaction.");}void Pay(){if(repairs.CurrentRow==null)return;int id=Convert.ToInt32(repairs.CurrentRow.Cells["MaPhieu"].Value);s.Pay(id);repairs.DataSource=s.Repairs();MessageBox.Show("Đã thanh toán phiếu.");}static string Prompt(string l,string v=""){using var f=new Form{Text=l,Width=400,Height=145,StartPosition=FormStartPosition.CenterParent};var t=new TextBox{Left=12,Top=20,Width=350,Text=v};var b=new Button{Text="OK",Left=280,Top=58,DialogResult=DialogResult.OK};f.Controls.AddRange(new Control[]{new Label{Text=l,Left=12,Top=2},t,b});f.AcceptButton=b;return f.ShowDialog()==DialogResult.OK?t.Text:"";}void Safe(Action a){try{a();}catch(Exception e){MessageBox.Show(e.Message,"Thông báo",MessageBoxButtons.OK,MessageBoxIcon.Warning);}}}